"""Executes the A2 notebook top to bottom (Restart & Run All equivalent) and saves it with all outputs."""
import base64, gzip, time
import nbformat
from nbclient import NotebookClient

NB_B64 = ""
open("A2_s4271512.ipynb", "wb").write(gzip.decompress(base64.b64decode(NB_B64)))
nb = nbformat.read("A2_s4271512.ipynb", as_version=4)
t0 = time.time()
client = NotebookClient(nb, timeout=-1, kernel_name="python3", resources={"metadata": {"path": "/kaggle/working"}})
try:
    client.execute()
    print("NOTEBOOK EXECUTED OK in %.1f min" % ((time.time() - t0) / 60))
finally:
    nbformat.write(nb, "A2_s4271512_executed.ipynb")
